package dev.zomboid.firstaid;
import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.client.player.LocalPlayer;import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.Button;import net.minecraft.world.item.ItemStack;import ichttt.mods.firstaid.FirstAid;
public class BlackoutChecks{
 static int count;static void ok(boolean b,String why){count++;if(!b)throw new AssertionError(why);}public static class Model{public boolean criticalConditionActive;public int ticks;public int getUnconsciousTicks(){return ticks;}}public static class Inventory{public List<ItemStack> items=new ArrayList<>();public int getContainerSize(){return items.size();}public Object getItem(int s){return items.get(s);}}public static class World{public long getGameTime(){return 0;}}
 public static void main(String[]a){Minecraft mc=Minecraft.getInstance();mc.player=new LocalPlayer();UnconsciousClient.tick();ok(mc.screen==null,"healthy play unaffected");mc.player.model.criticalConditionActive=true;mc.player.model.ticks=2000;Assist.self(mc.player);ok(Assist.attempts.isEmpty(),"native server refuses self revival without owned device");UnconsciousClient.tick();ok(mc.screen instanceof UnconsciousScreen,"downed opens dedicated black screen");UnconsciousScreen s=(UnconsciousScreen)mc.screen;ok(!s.isPauseScreen()&&!s.shouldCloseOnEsc(),"screen neither pauses rescue nor escapes to world");ok(!s.widgets.get(0).visible&&s.widgets.get(1).visible,"only waiting option without defibrillator");GuiGraphics g=new GuiGraphics();s.render(g,0,0,0);ok(g.fillColor==0xff000000&&g.keys.contains("firstaid.blackout.title"),"opaque black cover and translated title");s.widgets.get(1).press();g.keys.clear();s.render(g,0,0,0);ok(g.keys.contains("firstaid.blackout.waiting"),"waiting does not send revival request");ok(FirstAid.NETWORKING.sends==0,"no item no self revive packet");
 ItemStack defib=new ItemStack(true);mc.player.inventory.items.add(defib);s.tick();ok(s.widgets.get(0).visible&&s.widgets.get(0).active,"inventory defibrillator reveals get-up option");ok(Assist.defib(mc.player)==defib,"patched native server lookup finds exact owned stack");Assist.self(mc.player);ok(Assist.attempts.containsKey(mc.player),"native server accepts inventory-owned device through original self-revive route");Assist.attempts.clear();s.widgets.get(0).press();ok(FirstAid.NETWORKING.sends==1&&!s.widgets.get(0).active,"one explicit self revive request, no instant client heal");for(int i=0;i<99;i++)s.tick();ok(FirstAid.NETWORKING.sends==1,"does not retry automatically");s.tick();ok(s.widgets.get(0).active&&FirstAid.NETWORKING.sends==1,"failed attempt can be explicitly retried after timeout");mc.player.inventory.items.clear();s.tick();ok(!s.widgets.get(0).visible,"removing item removes revival option");ok(Assist.defib(mc.player)==null,"server cannot find removed device");
 mc.player.model.criticalConditionActive=false;mc.player.model.ticks=0;s.tick();ok(mc.screen==null,"helper revival closes unconscious screen");mc.player.inventory.items.add(defib);ok(Assist.defib(mc.player)==null,"healthy helper still needs device in hand, not inventory");mc.player.main=defib;ok(Assist.defib(mc.player)==defib,"original held-device lookup remains");mc.player.model.ticks=10;UnconsciousClient.tick();ok(mc.screen instanceof UnconsciousScreen&&!mc.screen.widgets.get(0).visible,"noncritical fainting cannot request native critical rescue");mc.player=null;UnconsciousClient.tick();ok(mc.screen==null,"disconnect clears obsolete blackout");System.out.println("BLACKOUT_UI_AND_NATIVE_INVENTORY_CHECKS="+count);}}
